"use client";

import Link from 'next/link';
import { useState } from 'react';

export default function Home() {
  return (
    <div>
      {/* Hero Section */}
      <div className="pt-8 pb-12 px-4">
          <div className="container mx-auto">
              <div className="w-full rounded-[2rem] overflow-hidden relative" style={{ background: 'linear-gradient(135deg, #111111 0%, #1a1a1a 40%, #ea580c 100%)', boxShadow: '0 20px 40px -10px rgba(234, 88, 12, 0.3)' }}>
                  <div className="py-24 px-8 text-center text-white relative z-10">
                      <h1 className="text-5xl md:text-6xl font-extrabold mb-4 tracking-tight">Potencialize seu Trabalho</h1>
                      <p className="text-xl md:text-2xl text-gray-300 font-light max-w-2xl mx-auto">
                          Ferramentas essenciais para gestão, documentos e processos executivos.
                      </p>
                  </div>
                  
                  {/* Decorative faint circles */}
                  <div className="absolute top-0 right-0 w-96 h-96 bg-orange-500 rounded-full blur-[120px] opacity-20 -mr-20 -mt-20"></div>
                  <div className="absolute bottom-0 left-0 w-80 h-80 bg-blue-900 rounded-full blur-[100px] opacity-20 -ml-20 -mb-20"></div>
              </div>
          </div>
      </div>

      {/* Cards Grid */}
      <div className="container mx-auto px-4 pb-20">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 max-w-5xl mx-auto">
              
              {/* PDF Tools Card */}
              <Link href="/pdf-tools" className="block group no-underline">
                  <div className="bg-white rounded-3xl p-10 text-center text-gray-800 shadow-sm border border-gray-100 h-full transition-all duration-300 hover:shadow-xl hover:-translate-y-1 hover:border-orange-100">
                      <div className="mb-6 inline-flex items-center justify-center w-20 h-20 rounded-2xl bg-orange-50 text-orange-600 mb-6 group-hover:scale-110 transition-transform duration-300">
                          <i className="fas fa-file-pdf text-4xl"></i>
                      </div>
                      <h3 className="text-2xl font-bold mb-3 group-hover:text-orange-600 transition-colors">Ferramentas PDF</h3>
                      <p className="text-gray-500 mb-8 leading-relaxed">
                          Comprimir, dividir, converter e redimensionar relatórios e documentos em PDF.
                      </p>
                      <span className="inline-block px-8 py-3 rounded-full border-2 border-orange-500 text-orange-600 font-bold hover:bg-orange-500 hover:text-white transition-all">
                          Acessar Ferramentas
                      </span>
                  </div>
              </Link>

              {/* BPMN Card */}
               <div className="relative group">
                  <div className="bg-white rounded-3xl p-10 text-center text-gray-800 shadow-sm border border-gray-100 h-full transition-all duration-300 hover:shadow-xl hover:-translate-y-1 hover:border-orange-100">
                      <div className="mb-6 inline-flex items-center justify-center w-20 h-20 rounded-2xl bg-orange-50 text-orange-600 mb-6 group-hover:scale-110 transition-transform duration-300">
                          <i className="fas fa-project-diagram text-4xl"></i>
                      </div>
                      <h3 className="text-2xl font-bold mb-3 group-hover:text-orange-600 transition-colors">Modelador BPMN</h3>
                      <p className="text-gray-500 mb-8 leading-relaxed">
                          Mapeie processos de negócio com o padrão BPMN 2.0. Exporte para apresentações.
                      </p>
                      <span className="inline-block px-8 py-3 rounded-full border-2 border-orange-500 text-orange-600 font-bold hover:bg-orange-500 hover:text-white transition-all cursor-pointer">
                          Abrir Editor
                      </span>
                  </div>
              </div>

               {/* Text Editor Card */}
               <Link href="/text-converter" className="block group no-underline md:col-span-2 max-w-2xl mx-auto w-full">
                  <div className="bg-white rounded-3xl p-10 text-center text-gray-800 shadow-sm border border-gray-100 h-full transition-all duration-300 hover:shadow-xl hover:-translate-y-1 hover:border-orange-100">
                      <div className="mb-6 inline-flex items-center justify-center w-20 h-20 rounded-2xl bg-orange-50 text-orange-600 mb-6 group-hover:scale-110 transition-transform duration-300">
                          <i className="fas fa-pen-nib text-4xl"></i>
                      </div>
                      <h3 className="text-2xl font-bold mb-3 group-hover:text-orange-600 transition-colors">Editor de Texto</h3>
                      <p className="text-gray-500 mb-8 leading-relaxed">
                          Ferramentas de correção, formatação e conversão de texto com exportação.
                      </p>
                      <span className="inline-block px-8 py-3 rounded-full border-2 border-orange-500 text-orange-600 font-bold hover:bg-orange-500 hover:text-white transition-all">
                          Abrir Ferramenta
                      </span>
                  </div>
              </Link>

          </div>
      </div>
    </div>
  );
}
